import{_ as e}from"./chunks/create-reservation.Csqbo4RE.js";import{_ as t,o as r,c as l,a2 as i}from"./chunks/framework.CWgsre3x.js";const f=JSON.parse('{"title":"Στοιχεία επιβάτη","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/passenger-information.md","filePath":"el/plus/passenger-information.md"}'),o={name:"el/plus/passenger-information.md"};function s(n,a,d,h,p,m){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="στοιχεια-επιβατη" tabindex="-1">Στοιχεία επιβάτη <a class="header-anchor" href="#στοιχεια-επιβατη" aria-label="Permalink to &quot;Στοιχεία επιβάτη&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Πηγαίος κώδικας TransferBook+ v0.7.9. Το παρόν είναι τοπικό προσχέδιο προς έλεγχο, όχι επιβεβαίωση διαθεσιμότητας στην παραγωγή. Ελέγξτε την εγκατεστημένη έκδοση και τα δικαιώματά σας.</p></div><h2 id="υποχρεωτικα-και-προαιρετικα-πεδια" tabindex="-1">Υποχρεωτικά και προαιρετικά πεδία <a class="header-anchor" href="#υποχρεωτικα-και-προαιρετικα-πεδια" aria-label="Permalink to &quot;Υποχρεωτικά και προαιρετικά πεδία&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Πεδίο</th><th>Απαίτηση</th></tr></thead><tbody><tr><td>Guest Full Name</td><td>Υποχρεωτικό</td></tr><tr><td>Phone</td><td>Υποχρεωτικό</td></tr><tr><td>Email (Optional)</td><td>Προαιρετικό</td></tr><tr><td>Flight / Vessel Details</td><td>Όπου χρειάζεται</td></tr><tr><td>Tablet Sign Text</td><td>Όπου χρειάζεται</td></tr></tbody></table><h2 id="κρατηση-μονο-με-τηλεφωνο" tabindex="-1">Κράτηση μόνο με τηλέφωνο <a class="header-anchor" href="#κρατηση-μονο-με-τηλεφωνο" aria-label="Permalink to &quot;Κράτηση μόνο με τηλέφωνο&quot;">​</a></h2><ol><li>Καταχωρίστε το πραγματικό όνομα και τηλέφωνο επικοινωνίας του επιβάτη.</li><li>Αφήστε το email κενό αν δεν παρέχεται. Μην επινοείτε email.</li><li>Προσθέστε στοιχεία πτήσης ή πλοίου εφόσον χρειάζονται. Ελέγξτε το κείμενο της πινακίδας.</li><li>Αποθηκεύστε μέσω της <a href="/el/plus/create-reservation.html">κανονικής διαδικασίας κράτησης</a>.</li></ol><h2 id="αναμενομενο-αποτελεσμα-και-προβληματα" tabindex="-1">Αναμενόμενο αποτέλεσμα και προβλήματα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα-και-προβληματα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα και προβλήματα&quot;">​</a></h2><p>Η απουσία email από μόνη της δεν εμποδίζει τη δημιουργία κράτησης. Διορθώστε μη έγκυρα στοιχεία χωρίς να τα επινοείτε. Δεν μπορεί να θεωρηθεί δεδομένη αποστολή email χωρίς διεύθυνση. Χρησιμοποιήστε τα στοιχεία μόνο για εξουσιοδοτημένους λειτουργικούς σκοπούς.</p><h2 id="εικονογραφημενα-πεδια-επιβατη" tabindex="-1">Εικονογραφημένα πεδία επιβάτη <a class="header-anchor" href="#εικονογραφημενα-πεδια-επιβατη" aria-label="Permalink to &quot;Εικονογραφημένα πεδία επιβάτη&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/create-reservation.png"><img src="'+e+'" alt="Τα πεδία Guest Full Name και Phone είναι υποχρεωτικά· το Email (Optional) μπορεί να παραμείνει κενό."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Τα πεδία Guest Full Name και Phone είναι υποχρεωτικά· το Email (Optional) μπορεί να παραμείνει κενό.</em></p><p>Αγγλικό περιβάλλον, λήψη δοκιμών v0.7.11· ενδεικτικά στοιχεία.</p><h2 id="αλλαγες-που-περιγραφονται-στην-v0-7-14" tabindex="-1">Αλλαγές που περιγράφονται στην v0.7.14 <a class="header-anchor" href="#αλλαγες-που-περιγραφονται-στην-v0-7-14" aria-label="Permalink to &quot;Αλλαγές που περιγράφονται στην v0.7.14&quot;">​</a></h2><p>Η έκδοση περιγράφει ειδικά αιτήματα επιβατών και εσωτερικές σημειώσεις αναθέσεων. Καταχωρίστε μόνο αναγκαίες πληροφορίες, διαχωρίστε τα αιτήματα πελατών από τις εσωτερικές σημειώσεις και επιβεβαιώστε την ορατότητα και τα δικαιώματα. Μην καταχωρίζετε περιττά ευαίσθητα στοιχεία. Το email επιβάτη παραμένει προαιρετικό. Η συμπεριφορά των πεδίων χρειάζεται αποδοχή στην εγκατεστημένη έκδοση.</p><p>Δείτε <a href="/el/security-privacy/">Ασφάλεια, ιδιωτικότητα και ΓΚΠΔ</a> και <a href="/el/release-notes/">Σημειώσεις εκδόσεων</a>.</p>',16)])])}const _=t(o,[["render",s]]);export{f as __pageData,_ as default};
